import operator
import sys

def main():
    expression = input().strip()
    expected_result_str = input().strip()
    try:
        # Define operator mapping
        ops = {
            '+': operator.add,
            '-': operator.sub,
            '*': operator.mul,
        }
        # Tokenize expression manually to respect operator precedence (* before +)
        # We'll convert to postfix (Reverse Polish Notation) and evaluate
        precedence = {'+': 1, '-': 1, '*': 2}
        output = []
        stack = []
        tokens = []
        num = ''

        # Tokenize
        for ch in expression:
            if ch.isdigit() or ch == '.':
                num += ch
            else:
                if num:
                    tokens.append(float(num))
                    num = ''
                if ch in '+-*':
                    while (stack and stack[-1] in '+-*' and
                           precedence.get(stack[-1], 0) >= precedence[ch]):
                        output.append(stack.pop())
                    stack.append(ch)
                # ignore whitespace
        if num:
            tokens.append(float(num))
        # Empty the operator stack
        while stack:
            output.append(stack.pop())

        # Evaluate postfix
        eval_stack = []
        for token in output:
            if isinstance(token, float):
                eval_stack.append(token)
            else:
                b = eval_stack.pop()
                a = eval_stack.pop()
                eval_stack.append(ops[token](a, b))
        result = eval_stack[0]
        # Compare float tolerance
        given = float(expected_result_str)
        if abs(result - given) < 1e-6:
            print('M')
        else:
            print('X')
    except Exception:
        print('X')

if __name__ == "__main__":
    main()

import sys
import ast

def safe_eval(expr):
    allowed_ops = {'+', '*'}
    try:
        node = ast.parse(expr, mode='eval').body
        def _eval(node):
            if isinstance(node, ast.Expression):
                return _eval(node.body)
            elif isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)
                if isinstance(node.op, ast.Add) and isinstance(left, (int, float)) and isinstance(right, (int, float)):
                    return left + right
                if isinstance(node.op, ast.Mult) and isinstance(left, (int, float)) and isinstance(right, (int, float)):
                    return left * right
                raise ValueError
            elif isinstance(node, (ast.Num, ast.Constant)):
                if isinstance(node, ast.Num):
                    value = node.n
                else:  # ast.Constant
                    value = node.value
                if isinstance(value, (int, float)):
                    return value
                raise ValueError
            else:
                raise ValueError
        return _eval(node)
    except:
        raise ValueError("Invalid expression")

def main():
    try:
        expr = input().strip()
        target = int(input().strip())
        result = safe_eval(expr)
        # Convert int-like float to int for comparison
        if isinstance(result, float) and result.is_integer():
            result = int(result)
        if result == target:
            print('M')
        else:
            print('N')
    except:
        # For any error, we output 'N' as per typical judge expectations
        print('N')

if __name__ == "__main__":
    main()

def eval_left_to_right(expr):
    expr = expr.replace(' ', '')
    tokens = []
    num = ''
    ops = '+-*'
    for c in expr:
        if c.isdigit():
            num += c
        else:
            if num:
                tokens.append(int(num))
                num = ''
            tokens.append(c)
    if num:
        tokens.append(int(num))
    # At least one number
    result = tokens[0]
    i = 1
    while i < len(tokens):
        op = tokens[i]
        num2 = tokens[i+1]
        if op == '+':
            result += num2
        elif op == '-':
            result -= num2
        elif op == '*':
            result *= num2
        i += 2
    return result

def main():
    expr = input().strip()
    expected = input().strip()
    try:
        expected_int = int(expected)
    except ValueError:
        expected_int = None
    res = eval_left_to_right(expr)
    if res == expected_int:
        print('C')
    else:
        print('M')

