import sys
from collections import deque, defaultdict

def main():
    input = sys.stdin.readline
    n_k = sys.stdin.readline().split()
    while len(n_k) < 2:
        n_k += sys.stdin.readline().split()
    n, k = map(int, n_k)

    grid = []
    while len(grid) < n:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.rstrip('\n')
        if line:
            grid.append(list(line))

    # 2D prefix sum for counting 'X'
    pre = [[0]*(n+1) for _ in range(n+1)]
    for i in range(n):
        for j in range(n):
            above = pre[i][j+1]
            left = pre[i+1][j]
            diag = pre[i][j]
            val = 1 if grid[i][j] == 'X' else 0
            pre[i+1][j+1] = above + left - diag + val

    def cnt_x(r1, c1, r2, c2):
        # Count number of 'X' in inclusive rectangle (r1,c1) to (r2,c2)
        return pre[r2+1][c2+1] - pre[r1][c2+1] - pre[r2+1][c1] + pre[r1][c1]

    # Find all connected components of '.' cells
    comp_id = [[-1]*n for _ in range(n)]
    comp_sizes = []
    cid = 0
    dir4 = [(-1,0),(1,0),(0,-1),(0,1)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.' and comp_id[i][j] == -1:
                q = deque()
                q.append((i, j))
                comp_id[i][j] = cid
                cnt = 1
                while q:
                    x, y = q.popleft()
                    for dx, dy in dir4:
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < n and 0 <= ny < n and grid[nx][ny]=='.' and comp_id[nx][ny]==-1:
                            comp_id[nx][ny] = cid
                            cnt += 1
                            q.append((nx,ny))
                comp_sizes.append(cnt)
                cid += 1

    # For each X, record adjacent component ids (set)
    adj_list = [[[] for _ in range(n)] for __ in range(n)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'X':
                seen = set()
                for dx, dy in dir4:
                    ni, nj = i+dx, j+dy
                    if 0<=ni<n and 0<=nj<n and grid[ni][nj]=='.' and comp_id[ni][nj]!=-1:
                        seen.add(comp_id[ni][nj])
                adj_list[i][j] = list(seen)

    is_X = [[grid[i][j]=='X' for j in range(n)] for i in range(n)]

    # For each row, for each window of size k, store the set of adjacent component ids
    S_row = [[set() for _ in range(n - k + 1)] for __ in range(n)]
    for i in range(n):
        cnt = defaultdict(int)
        left = 0
        for right in range(n):
            # Add cell at (i, right) to window if it's X
            if is_X[i][right]:
                for cid in adj_list[i][right]:
                    if cid == -1:  # skip invalid
                        continue
                    cnt[cid] += 1
            # Shrink window if too large
            if right - left + 1 > k:
                if is_X[i][left]:
                    for cid in adj_list[i][left]:
                        if cid == -1:
                            continue
                        cnt[cid] -= 1
                        if cnt[cid] == 0:
                            del cnt[cid]
                left += 1
            # If window is complete, record
            if right >= k-1:
                S_row[i][right-k+1] = set(cnt.keys())

    # Now, for each k x k square, compute union of adjacent components
    max_ans = max(comp_sizes) if comp_sizes else 0

    for i0 in range(n - k + 1):
        for j0 in range(n - k + 1):
            # Union of all adjacent component ids in this square
            comp_set = set()
            for di in range(k):
                comp_set |= S_row[i0+di][j0]
            # Number of X's in this square
            x_cnt = cnt_x(i0, j0, i0+k-1, j0+k-1)
            total = x_cnt
            for cid in comp_set:
                if 0 <= cid < len(comp_sizes):
                    total += comp_sizes[cid]
            if total > max_ans:
                max_ans = total

    # In case the entire grid is blocked, the only component possible is k*k after flipping
    # But code above already handles that (x_cnt will be k*k, comp_set empty)
    print(max_ans)

if __name__ == '__main__':
    main()

