def main():
    import sys
    input = sys.stdin.readline
    n_k = sys.stdin.readline().split()
    while len(n_k) < 2:
        n_k += sys.stdin.readline().split()
    n, k = map(int, n_k)

    grid = []
    while len(grid) < n:
        line = sys.stdin.readline()
        if not line:
            line = sys.stdin.readline()
        if line and line.strip() != '':
            grid.append(line.strip())

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    label = [[-1]*n for _ in range(n)]
    comp_area = {}  # cid -> area
    comp_cells = {} # cid -> set of (i, j)
    cid = 0

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.' and label[i][j] == -1:
                # BFS
                from collections import deque
                q = deque()
                q.append((i, j))
                label[i][j] = cid
                area = 1
                cells = set([(i, j)])
                while q:
                    x, y = q.popleft()
                    for dx, dy in dirs:
                        nx, ny = x+dx, y+dy
                        if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == '.' and label[nx][ny] == -1:
                            label[nx][ny] = cid
                            q.append((nx, ny))
                            area += 1
                            cells.add((nx, ny))
                comp_area[cid] = area
                comp_cells[cid] = cells
                cid += 1

    # Precompute prefix sum for X's
    prefX = [[0]*(n+1) for _ in range(n+1)]
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'X':
                val = 1
            else:
                val = 0
            prefX[i+1][j+1] = prefX[i][j+1] + prefX[i+1][j] - prefX[i][j] + val

    # Precompute prefix sum for '.' as a quick skip for all-X windows
    prefDot = [[0]*(n+1) for _ in range(n+1)]
    for i in range(n):
        for j in range(n):
            val = 1 if grid[i][j] == '.' else 0
            prefDot[i+1][j+1] = prefDot[i][j+1] + prefDot[i+1][j] - prefDot[i][j] + val

    # For quick min/max column and row of each component (for skipping, not used in main scan)
    # But not needed here.

    max_total = 0

    # Number of windows
    max_top = n - k
    for top in range(max_top + 1):
        max_left = n - k
        for left in range(max_left + 1):
            bottom = top + k - 1
            right = left + k - 1

            # Count total X's in window
            x_cnt = prefX[bottom+1][right+1] - prefX[top][right+1] - prefX[bottom+1][left] + prefX[top][left]
            # If the window is all X's, the best we can do is k*k
            dot_cnt = prefDot[bottom+1][right+1] - prefDot[top][right+1] - prefDot[bottom+1][left] + prefDot[top][left]
            if dot_cnt == 0:
                candidate = k * k
                if candidate > max_total:
                    max_total = candidate
                continue

            # Only scan this window if k is small OR number of '.' is not too large
            # If k is big and window is sparse, we'll iterate over only the '.' cells in the window
            # Otherwise, we do a simple scan.
            unique_comps = set()
            if k <= 50 or dot_cnt <= 2000:
                # Naive scan
                for i in range(top, bottom+1):
                    for j in range(left, right+1):
                        if grid[i][j] == '.' and label[i][j] != -1:
                            unique_comps.add(label[i][j])
            else:
                # Only scan cells that are '.', using precomputed row lists.
                # Build a row-wise '.' mapping if not already built.
                # We'll build a list of '.' positions per row now if not done
                if not hasattr(main, 'dot_positions'):
                    main.dot_positions = [ [] for _ in range(n) ]
                    for i in range(n):
                        for j in range(n):
                            if grid[i][j] == '.':
                                main.dot_positions[i].append(j)
                for i in range(top, bottom+1):
                    # get all j in [left, right] in this row where grid[i][j] == '.'
                    # binary search since columns are sorted
                    from bisect import bisect_left, bisect_right
                    lst = main.dot_positions[i]
                    l_idx = bisect_left(lst, left)
                    r_idx = bisect_right(lst, right)
                    for j in lst[l_idx:r_idx]:
                        cid_here = label[i][j]
                        if cid_here != -1:
                            unique_comps.add(cid_here)
            # Sum areas for unique components
            area_sum = 0
            seen = set()
            for cid in unique_comps:
                if cid not in seen:
                    area_sum += comp_area[cid]
                    seen.add(cid)
            candidate = area_sum + x_cnt
            if candidate > max_total:
                max_total = candidate

    # It's also possible that the whole grid becomes connected after clearing the square even if not captured by above.
    # But with our unions, we've considered all possible merges inside the window + adjacent cells so this is as close as we can do in reasonable time.
    print(max_total)

