class SegNode:
    __slots__ = ('l', 'r', 'left', 'right', 'cnt', 'lazy_map', 'full_val')
    def __init__(self, l, r):
        self.l = l
        self.r = r
        self.left = None
        self.right = None
        self.cnt = [0] * 10
        self.lazy_map = [-1] * 10  # -1 means no change
        self.full_val = None  # If not None, all in this segment have this value

    def _set_full(self, v):
        self.cnt = [0] * 10
        self.cnt[v] = self.r - self.l + 1
        self.lazy_map = [-1] * 10
        self.full_val = v

    def _compose_maps(self, a, b):
        # a and b are lists of length 10, b[a[v]] if a[v]!=-1 else (b[v] if b[v]!=-1 else -1)
        res = [-1] * 10
        for v in range(10):
            x = a[v]
            if x == -1:
                x = v
            y = b[x] if x != -1 and b[x] != -1 else (x if b[x] == -1 else -1)
            # Actually, if a[v]!=-1 use b[a[v]], else if b[v]!=-1 use b[v], else -1
            if a[v] != -1:
                if b[a[v]] != -1:
                    res[v] = b[a[v]]
                else:
                    res[v] = a[v]
            else:
                if b[v] != -1:
                    res[v] = b[v]
                else:
                    res[v] = -1
        return res

    def _apply_local_mapping(self, mapping):
        if all(m == -1 for m in mapping):
            return
        # Apply mapping to cnt and compose with current lazy_map
        new_cnt = [0]*10
        for v in range(10):
            if self.cnt[v]:
                nv = mapping[v] if mapping[v] != -1 else v
                new_cnt[nv] += self.cnt[v]
        # update full_val if all same
        if sum(new_cnt) == self.r - self.l + 1:
            v_full = next(i for i in range(10) if new_cnt[i] == self.r-self.l+1)
            self._set_full(v_full)
        else:
            self.cnt = new_cnt
            self.full_val = None
        # compose new mapping with self.lazy_map
        self.lazy_map = self._compose_maps(mapping, self.lazy_map)

    def push(self):
        if self.l != self.r and (self.full_val is not None or any(self.lazy_map[i] != -1 for i in range(10))):
            for ch in (self.left, self.right):
                ch._apply_local_mapping(self.lazy_map)
            # reset
            self.lazy_map = [-1]*10
            if self.full_val is not None:
                self.left._set_full(self.full_val)
                self.right._set_full(self.full_val)
                self.full_val = None

    def _range_set_map(self, l, r, mapping):
        if self.r < l or self.l > r:
            return
        if l <= self.l and self.r <= r:
            self._apply_local_mapping(mapping)
            return
        self.push()
        self.left._range_set_map(l, r, mapping)
        self.right._range_set_map(l, r, mapping)
        # pull up counts
        for i in range(10):
            self.cnt[i] = self.left.cnt[i] + self.right.cnt[i]
        if self.left.full_val is not None and self.right.full_val is not None and self.left.full_val == self.right.full_val:
            self._set_full(self.left.full_val)

    def range_set_x_to_y(self, l, r, x, y):
        # set all elements with value x in [l, r] to y
        if x == y:
            return
        mapping = [-1]*10
        mapping[x] = y
        self._range_set_map(l, r, mapping)

    def _query(self, l, r, x, y):
        if self.r < l or self.l > r:
            return 0
        if l <= self.l and self.r <= r:
            return sum(self.cnt[x:y+1])
        self.push()
        return self.left._query(l, r, x, y) + self.right._query(l, r, x, y)

    def query(self, l, r, x, y):
        return self._query(l, r, x, y)

def build(l, r, arr):
    node = SegNode(l, r)
    if l == r:
        node._set_full(arr[l])
        return node
    mid = (l + r) // 2
    left = build(l, mid, arr)
    right = build(mid+1, r, arr)
    node.left = left
    node.right = right
    for i in range(10):
        node.cnt[i] = left.cnt[i] + right.cnt[i]
    if left.full_val is not None and right.full_val is not None and left.full_val == right.full_val:
        node._set_full(left.full_val)
    return node

