        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                dq.append(v)

    # Euler Tour: in_time, out_time (0-based)
    in_time = [0]*n
    out_time = [0]*n
    time = 0
    stack = [(0, False)]
    while stack:
        node, processed = stack.pop()
        if not processed:
            in_time[node] = time
            time += 1
            stack.append((node, True))
            for c in reversed(children[node]):
                stack.append((c, False))
        else:
            out_time[node] = time-1

    # ---------------- Segment Tree ----------------
    class Node:
        __slots__ = ['l','r','left','right','counts','lazy']
        def __init__(self, l, r):
            self.l = l
            self.r = r
            self.left = None
            self.right = None
            self.counts = [0]*10
            self.lazy = None # (x, y)

    def build(l, r):
        nd = Node(l, r)
        if l == r:
            nd.counts[0] = 1
        else:
            m = (l + r)//2
            nd.left = build(l, m)
            nd.right = build(m+1, r)
            for i in range(10):
                nd.counts[i] = nd.left.counts[i] + nd.right.counts[i]
        return nd

    root = build(0, n-1)

    def push(nd):
        if nd.lazy is None or nd.l == nd.r:
            return
        x, y = nd.lazy
        # apply to left
        if nd.left:
            old_l = nd.left.counts[:]
            nd.left.counts = [0]*10
            nd.left.counts[y] = old_l[x]
            if nd.left.lazy is None:
                nd.left.lazy = (x, y)
            else:
                nd.left.lazy = (x, y)  # Overwrite: last set wins
        # apply to right
        if nd.right:
            old_r = nd.right.counts[:]
            nd.right.counts = [0]*10
            nd.right.counts[y] = old_r[x]
            if nd.right.lazy is None:
                nd.right.lazy = (x, y)
            else:
                nd.right.lazy = (x, y)
        nd.lazy = None  # clear current node's lazy

    def update(nd, l, r, ql, qr, x, y):
        if nd.r < ql or nd.l > qr:
            return
        if ql <= nd.l and nd.r <= qr:
            old = nd.counts[:]
            nd.counts = [0]*10
            nd.counts[y] = old[x]
            if nd.l != nd.r:
                nd.lazy = (x, y)
            return
        push(nd)
        update(nd.left, l, r, ql, qr, x, y)
        update(nd.right, l, r, ql, qr, x, y)
        for i in range(10):
            nd.counts[i] = nd.left.counts[i] + nd.right.counts[i]

