def tokenize(s):
    """
    Tokenize the program string according to the rules in the problem.
    Returns a list of tuples: (type, value)
        type: 'STRING', 'WORD', or 'SYMBOL'
    """
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '"':
            # Capture string literal
            j = i + 1
            while j < n and s[j] != '"':
                j += 1
            tokens.append(('STRING', s[i+1:j]))
            i = j + 1 if j < n and s[j] == '"' else j
        elif c in ';':
            tokens.append(('SYMBOL', c))
            i += 1
        elif c.isspace():
            i += 1
        else:
            # Alphanumeric word
            j = i
            while j < n and s[j].isalnum():
                j += 1
            if j > i:
                tokens.append(('WORD', s[i:j]))
                i = j
            else:
                i += 1  # skip unknown char (problem guarantees only valid chars)
    return tokens

def are_close(t1, t2):
    """
    Return True if t1 and t2 represent two programs that are 'CLOSE' according to the rules:
        - All tokens are the same type and value except for exactly one 'STRING' token
        - Or the token lists differ in length by one at either end and that token is a STRING token,
          and all other tokens match in order and value.
    """
    # IDENTICAL
    if t1 == t2:
        return False  # we'll handle this separately as IDENTICAL in main
    n1, n2 = len(t1), len(t2)
    # Case 1: same length, exactly one string differs, others identical
    if n1 == n2:
        diff_indices = []
        for idx, (a, b) in enumerate(zip(t1, t2)):
            if a == b:
                continue
            if a[0] != 'STRING' or b[0] != 'STRING':
                return False  # non-string mismatch
            # Both are strings
            if a[1] != b[1]:
                diff_indices.append(idx)
                if len(diff_indices) > 1:
                    return False
        if len(diff_indices) == 1:
            # All non-string tokens already checked (must match)
            # Just to be extra sure
            for idx, (a, b) in enumerate(zip(t1, t2)):
                if a[0] != 'STRING' and a != b:
                    return False
            return True
        else:
            return False
    # Case 2: lengths differ by 1
    if abs(n1 - n2) == 1:
        # Check if the only difference is a string at the front or the end
        if n1 > n2:
            s_long, s_short = t1, t2
        else:
            s_long, s_short = t2, t1
        # Check trailing string
        if s_long[-1][0] == 'STRING' and s_long[:-1] == s_short:
            # No other difference
            return True
        # Check leading string
        if s_long[0][0] == 'STRING' and s_long[1:] == s_short:
            return True
        return False
    # Otherwise, not CLOSE
    return False

def main():
    import sys
    lines = [line.rstrip('\n') for line in sys.stdin.read().splitlines()]
    idx = 0
    while idx < len(lines):
        # Skip empty lines if any
        if idx >= len(lines):
            break
        if lines[idx].strip() == '':
            idx += 1
            continue
        if lines[idx] == '.':
            break
        if idx + 1 >= len(lines):
            break  # malformed input
        s1 = lines[idx]
        s2 = lines[idx+1]
        t1 = tokenize(s1)
        t2 = tokenize(s2)
        if t1 == t2:
            print('IDENTICAL')
        elif are_close(t1, t2):
            print('CLOSE')
        else:
            print('DIFFERENT')
        idx += 2

