import sys

def tokenize(code):
    tokens = []
    i = 0
    n = len(code)
    in_string = False
    buf = ''
    while i < n:
        ch = code[i]
        if ch == '"':
            if in_string:
                # End of string literal
                tokens.append('"' + buf + '"')
                buf = ''
                in_string = False
            else:
                in_string = True
        elif in_string:
            buf += ch
        else:
            if ch == ';':
                if buf:
                    tokens.append(buf)
                    buf = ''
                tokens.append(';')
            else:
                buf += ch
        i += 1
    # flush remaining data
    if in_string:
