import sys
import re

def tokenize(s):
    """
    Splits the program string into a sequence of ('UNQUOTE', text) or ('QUOTE', text) tuples.
    Quoted substrings are detected using non-greedy matching on double quotes.
    """
    parts = re.split(r'(".*?")', s)
    tokens = []
    i = 0
    n = len(parts)
    while i < n:
        part = parts[i].rstrip('\n')
        if i % 2 == 0:
            # Unquoted part
            if part:
                tokens.append(('UNQUOTE', part))
        else:
            # Quoted part (should start and end with ")
            if part and len(part) >= 2 and part[0] == '"' and part[-1] == '"':
                # Extract the content inside the quotes
                content = part[1:-1]
                tokens.append(('QUOTE', content))
            else:
                # Per the problem statement this shouldn't happen, but treat as unquoted for safety
                if part:
                    tokens.append(('UNQUOTE', part))
        i += 1
    return tokens

def main():
    lines = sys.stdin.read().splitlines()
    i = 0
    while i + 1 < len(lines):
        s1 = lines[i]
        s2 = lines[i + 1]
        # Stop if a line is the period that marks the end
        if s1.strip() == '.' or s2.strip() == '.':
            break
        t1 = tokenize(s1)
        t2 = tokenize(s2)
        # Token count must match for CLOSE or IDENTICAL
        if len(t1) != len(t2):
            print("DIFFERENT")
            i += 2
            continue
        quote_diffs = 0
        mismatch = False
        for (typ1, val1), (typ2, val2) in zip(t1, t2):
            if typ1 != typ2 or val1 != val2:
                if typ1 == 'QUOTE' and typ2 == 'QUOTE':
                    if val1 != val2:
                        quote_diffs += 1
                else:
                    # If not both quote tokens, and they differ, it's a mismatch
                    mismatch = True
                    break
        if mismatch:
            print("DIFFERENT")
        elif quote_diffs == 0:
            print("IDENTICAL")
        elif quote_diffs == 1:
            print("CLOSE")
        else:
            print("DIFFERENT")
        i += 2

if __name__ == "__main__":
    main()

