import re

def extract_string_literals(source):
    """
    Extracts string literals (contents between double quotes) as a list, preserving order.
    """
    # This regex captures text inside double quotes, allowing escaped quotes for completeness
    # But the problem statement does not mention escapes, so we'll just take everything between quotes.
    # We'll use a non-greedy match and find all occurrences.
    string_literals = re.findall(r'".*?"', source)
    # Remove the surrounding double quotes from each literal (strip once per quote pair)
    return [lit[1:-1] for lit in string_literals]

def main():
