from collections import defaultdict

def main():
    sys.setrecursionlimit(1 << 25)
    input = sys.stdin.readline
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        graph = [[] for _ in range(n + 1)]
        for __ in range(m):
            a, b = map(int, input().split())
            if a != b:
                graph[a].append(b)
                graph[b].append(a)

        parent = list(range(n + 1))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u
        def union(u, v):
            ru, rv = find(u), find(v)
            if ru != rv:
                parent[rv] = ru

        for v in range(1, n + 1):
            for nb in graph[v]:
                union(v, nb)

        comp = defaultdict(list)
        for node in range(1, n + 1):
            root = find(node)
            comp[root].append(node)

        p = [0] * (n + 1)
        q = [0] * (n + 1)
        next_id = 1
        for nodes in comp.values():
            nodes_sorted = sorted(nodes)
            k = len(nodes_sorted)
            for i, node in enumerate(nodes_sorted):
                p[node] = next_id + i
            for i, node in enumerate(nodes_sorted):
                q[node] = next_id + k - 1 - i
            next_id += k

        print(' '.join(str(p[i]) for i in range(1, n + 1)))
        print(' '.join(str(q[i]) for i in range(1, n + 1)))

