def main():
    input = sys.stdin.readline
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        grid = [list(input().strip()) for _ in range(n)]
        ops = []
        # Sweep all but the last row and column, clearing cell by cell
        for i in range(n-1):
            for j in range(m-1):
                if grid[i][j] == '1':
                    # Use 2x2 at (i,j): operate on (i,j), (i,j+1), (i+1,j)
                    x1, y1 = i+1, j+1
                    x2, y2 = i+1, j+2
                    x3, y3 = i+2, j+1
                    ops.append((x1, y1, x2, y2, x3, y3))
                    # Flip the three cells
                    for dx, dy in ((0,0), (0,1), (1,0)):
                        grid[i+dx][j+dy] = '1' if grid[i+dx][j+dy] == '0' else '0'
        # Now handle the last row (except the last cell)
        for j in range(m-2):
            if grid[n-1][j] == '1':
                # Use the 2x2 at (n-2, j): operate on (n-1,j), (n-1,j+1), (n-2,j+1)
                x1, y1 = n, j+1
                x2, y2 = n, j+2
                x3, y3 = n-1, j+2
                ops.append((x1, y1, x2, y2, x3, y3))
                # Flip the three cells
                for dx, dy in ((0,0), (0,1), (-1,1)):
                    ni, nj = n-1+dx, j+dy
                    if 0 <= ni < n and 0 <= nj < m:
                        grid[ni][nj] = '1' if grid[ni][nj] == '0' else '0'
        # Now handle the last column (except the last cell)
        for i in range(n-2):
            if grid[i][m-1] == '1':
                # Use the 2x2 at (i, m-2): operate on (i+1, m), (i+2, m), (i+1, m-1)
                x1, y1 = i+1, m
                x2, y2 = i+2, m
                x3, y3 = i+1, m-1
                ops.append((x1, y1, x2, y2, x3, y3))
                # Flip the three cells
                for dx, dy in ((0,0), (1,0), (0,-1)):
                    ni, nj = i+dx, m-1+dy
                    if 0 <= ni < n and 0 <= nj < m:
                        grid[ni][nj] = '1' if grid[ni][nj] == '0' else '0'
        # Output
        print(len(ops))
        for op in ops:
            print(*op)

