import sys

def get_max_point_ratio_to_score(r):
    if r <= 1/32:
        return 2500
    elif r <= 1/16:
        return 2000
    elif r <= 1/8:
        return 1500
    elif r <= 1/4:
        return 1000
    elif r <= 1/2:
        return 500
    else:
        return 0

def get_yj_thresholds(n_plus_k, orig_solved):
    """
    Return the possible y_j values that can push the solved count into a different scoring tier.
    Always include y_j = 0 and y_j = k (where k is up to the theoretical max, but we only use up to the current k in main).
    """
    thresholds = [
        0,  # y_j=0
        # These are the minimal number of additional solvers to reach the next interval:
        # For each threshold ratio r_th (from the scoring table), solve for y_j:
        # (orig_solved + y_j) / (n_plus_k) > r_th   <=> y_j > r_th * n_plus_k - orig_solved
        # We'll compute the y_j that crosses into the next interval:
        # Boundaries: 1/32, 1/16, 1/8, 1/4, 1/2
        # Use float(math.ceil)
        thres_ratios = [1/32, 1/16, 1/8, 1/4, 1/2]
        plus = []
        n_k = n_plus_k
        for r_th in thres_ratios:
            # minimal y_j to just cross this threshold (strictly greater)
            y_min = int(r_th * n_k - orig_solved) + 1
            if y_min > 0 and 0 < y_min <= n_k:
                plus.append(y_min)
        # Always add y_j = min(n_k, something large)
        plus.append(n_k)
        # Remove duplicates and sort
        ret = set()
        ret.add(0)
        for t in plus:
            ret.add(t)
        slist = sorted(ret)
        # Remove values > n_plus_k
        return [y for y in slist if 0 <= y <= n_plus_k]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    idx = 0
    n = int(data[idx]); idx += 1
    submissions = []
    for _ in range(n):
        row = list(map(int, data[idx:idx+5])); idx += 5
        submissions.append(row)

    vasya = submissions[0]
    petya = submissions[1]
    vasya_solved = [x != -1 for x in vasya]

    solved_by = []
    for j in range(5):
        s = set()
        for i in range(n):
            if submissions[i][j] != -1:
                s.add(i)
        solved_by.append(s)

    MAX_K = 2500  # safe upper; the third sample answer is 27, so 2500 is enough for constraints

    # Precompute, for any k and problem j, the possible y_j to enumerate (only fractions that change the max_point)
    def candidate_yjs(n_plus_k, orig_solved):
        # Special: If orig_solved == n_plus_k, further increasing y_j doesn't help.
        if orig_solved == n_plus_k:
            return [0]
        # We will always have y_j=0 and y_j = n_plus_k
        # For each threshold, compute min y_j to cross it
        thres_ratios = [1/32, 1/16, 1/8, 1/4, 1/2]
        cand = set([0, n_plus_k])
        for r_th in thres_ratios:
            # minimal y_j so that (orig_solved + y_j) / n_plus_k > r_th
            # y_j > r_th * n_plus_k - orig_solved
            y_needed = int(r_th * n_plus_k - orig_solved) + 1
            # clamp to [0, n_plus_k]
            if 0 < y_needed <= n_plus_k:
                cand.add(y_needed)
            # Also, the maximal y_j that still keeps the ratio strictly less than r_th (i.e., one before jump)
            y_prev = int(r_th * n_plus_k - orig_solved)
            if 0 <= y_prev < n_plus_k:
                cand.add(y_prev)
        # Remove invalid
        return sorted([y for y in cand if 0 <= y <= n_plus_k])

    # DP over problems, for each k
    for k in range(0, MAX_K+1):
        n_plus_k = n + k
        # Precompute, for each problem j, the y_j candidates for this k
        problem_candidates = []
        for j in range(5):
            if vasya_solved[j]:
                y_candidates = candidate_yjs(n_plus_k, len(solved_by[j]))
            else:
                # cannot add corrects
                y_candidates = [0]
            problem_candidates.append(y_candidates)

        # DP: key: allocated_correct => best diff (Vasya - Petya)
        dp = {0: 0.0}

        for j in range(5):
            cands = problem_candidates[j]
            next_dp = {}
            orig_solved_j = len(solved_by[j])
            for allocated_so_far, diff_prev in dp.items():
                for y_j in cands:
                    if allocated_so_far + y_j > k:
                        continue
                    # total solvers including new corrects from Vasya's accounts (only if he solved)
                    if vasya_solved[j]:
                        total_solved_j = orig_solved_j + y_j
                    else:
                        total_solved_j = orig_solved_j
                    mp = get_max_point_ratio_to_score(total_solved_j / n_plus_k)
                    # Vasya's points
                    if vasya[j] == -1:
                        v_pts = 0.0
                    else:
                        v_pts = mp * (1 - vasya[j]/250.0)
                    # Petya's points
                    if petya[j] == -1:
                        p_pts = 0.0
                    else:
                        p_pts = mp * (1 - petya[j]/250.0)
                    new_allocated = allocated_so_far + y_j
                    diff_new = diff_prev + (v_pts - p_pts)
                    if new_allocated not in next_dp or diff_new > next_dp[new_allocated]:
                        next_dp[new_allocated] = diff_new
            dp = next_dp
            if not dp:
                break   # impossible to allocate at this stage, break inner loop

        # After all problems, check if any allocation gives Vasya > Petya
        best_diff = -float('inf')
        for diff in dp.values():
            if diff > 1e-8:
                print(k)
                return

    print(-1)

