def main():
    input = sys.stdin.readline
    n = int(input())
    submissions = []
    for _ in range(n):
        arr = list(map(int, input().split()))
        submissions.append(arr)

    vasya = submissions[0]
    petya = submissions[1]
    orig_n = n

    # For each problem: who solved it (participant index set)
    base_solved = []
    for j in range(5):
        solved_set = set()
        for i in range(n):
            t = submissions[i][j]
            if t != -1 and 0 <= t <= 119:
                solved_set.add(i)
        base_solved.append(len(solved_set))

    # Which problems has Vasya solved?
    vasya_solved = [ (t != -1 and 0 <= t <= 119) for t in vasya ]
    solved_indices = [j for j in range(5) if vasya_solved[j]]
    m = len(solved_indices)

    def is_possible(t):
        # For each pattern: for each of the m problems Vasya solved, new correct submissions = 0 or t
        for bits in product([0, t], repeat=m):
            x_vec = [0]*5   # x_vec[j]: new correct submissions for problem j
            for idx, j in enumerate(solved_indices):
                if bits[idx] == t:
                    x_vec[j] = t
            total_part = orig_n + t
            v_score = 0.0
            p_score = 0.0
            for j in range(5):
                total_solved = base_solved[j] + x_vec[j]
                # Avoid division by zero, but t>=0 and n>=2 so total_part>=2 always
                frac = total_solved / total_part
                mx = score_fraction(frac)
                # Vasya's score for this problem
                if vasya[j] != -1 and 0 <= vasya[j] <= 119:
                    v_score += mx * (1 - vasya[j] / 250.0)
                # Petya's score for this problem
                if petya[j] != -1 and 0 <= petya[j] <= 119:
                    p_score += mx * (1 - petya[j] / 250.0)
            # Compare with enough precision
            if v_score > p_score + 1e-8:
                return True
        return False

    lo, hi = 0, 2000000   # 2e6 is more than enough as per constraints and samples
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if is_possible(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    print(ans if ans != -1 else -1)

