def count_operations(a, b):
    count = 0
    while a > 0 and b > 0:
        if a >= b:
            count += a // b
            a %= b
        else:
            count += b // a
            b %= a
        # After modulo, one may become zero, so check and break if needed
        if a == 0 or b == 0:
            break
    # If one is non-zero, the remaining operations equal the value itself (subtract 1 each time)
    if a == 0:
        count += b
    elif b == 0:
        count += a
    return count

