        for p in rev_edges[v]:
            if not vis2[p]:
                vis2[p] = True
                can_reach_N.add(p)
                stack.append(p)

    # 3. Bellman-Ford for max path (N-1 relaxations), maximizing the score
    NEG_INF = -10**30
    dist = [NEG_INF]*(N+1)
    dist[1] = 0

    for _ in range(N-1):
        updated = False
        for a, b, c in edges:
            if dist[a] != NEG_INF and dist[a] + c > dist[b]:
                dist[b] = dist[a] + c
                updated = True
        if not updated:
            break

    # 4. Check for positive cycles on a path from 1 to N
    has_infinite = False
    for a, b, c in edges:
        if dist[a] != NEG_INF and dist[a] + c > dist[b]:
            # Only consider if the improved node can be used in an infinite loop to N
            if b in reach_from_1 and b in can_reach_N:
                has_infinite = True
                break

    if has_infinite:
        print('inf')
    elif dist[N] == NEG_INF:
        # By problem statement, this shouldn't happen.
        print('inf')
    else:
        print(dist[N])

