import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 2)
    def update(self, idx, delta):
        while idx <= self.n:
            self.bit[idx] += delta
            idx += idx & -idx
    def query(self, idx):
        s = 0
        while idx > 0:
            s += self.bit[idx]
            idx -= idx & -idx
        return s

def main():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        line = line.strip()
        if not line:
            continue
        A, B, P = map(int, line.split())
        if A == 0 and B == 0 and P == 0:
            break
        n = B - A + 1
        if n == 0:
            print(0)
            continue
        S = [str(x) for x in range(A, B + 1)]
        # Coordinate compression
        sorted_strs = sorted(set(S))
        str_to_rank = {s: i + 1 for i, s in enumerate(sorted_strs)}  # 1-based
        n_unique = len(sorted_strs)
        ft = Fenwick(n_unique)
        total_dp = 0
        for s in S:
            r = str_to_rank[s]
            prev = ft.query(r - 1)
            dp_i = 1 + prev
            total_dp += dp_i
            ft.update(r, dp_i)
        print(total_dp % P)

