import bisect

def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(math.isqrt(limit)) + 1):
        if is_prime[i]:
            for j in range(i*i, limit+1, i):
                is_prime[j] = False
    primes = [i for i, v in enumerate(is_prime) if v]
    return primes

def main():
    input_lines = sys.stdin.read().splitlines()
    triplets = []
    max_m = 0
    for line in input_lines:
        if not line.strip():
            continue
        m, a, b = map(int, line.strip().split())
        if m == 0 and a == 0 and b == 0:
            break
        triplets.append((m, a, b))
        if m > max_m:
            max_m = m

    # Generate all primes up to max_m
    primes = sieve_of_eratosthenes(max_m)
    primes.sort()

    for m_val, a_val, b_val in triplets:
        ratio_min = a_val / b_val
        max_area = 0
        best_p = best_q = 2

        # For each possible width p (prime), find the best height q (also prime)
        for idx, p in enumerate(primes):
            if p > m_val:
                break
            max_q_val = m_val // p
            if max_q_val < p:
                continue
            q_limit = p * b_val // a_val  # maximum q to keep ratio >= a/b
            upper = min(max_q_val, q_limit)
            if upper < p:
                continue

            # Find the largest prime q in [p, upper]
            # bisect_left finds first prime >= p, bisect_right finds first prime > upper
            left = bisect.bisect_left(primes, p, idx)
            right = bisect.bisect_right(primes, upper, left)
            if right > left:
                q = primes[right - 1]
                # Double-check the ratio (usually always satisfied, but just in case)
                if q >= p and p / q >= ratio_min:
                    area = p * q
                    if area > max_area:
                        max_area = area
                        best_p = p
                        best_q = q

        # If for some case no pair found, default to (2,2)
        if max_area == 0:
            if 2 * 2 <= m_val and 1 >= ratio_min:
                best_p, best_q = 2, 2
        print(f"{best_p} {best_q}")

