def find_fixed_point(arr):
    n = len(arr)
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            # Check for the smallest fixed point in case of duplicates
            while mid > left and arr[mid - 1] == mid - 1:
                mid -= 1
            return mid
        elif arr[mid] < mid:
            left = mid + 1
        else:
            right = mid - 1
    # If no fixed point found, return -1 (though problem sample always has one)
    return -1

