def main():
    while True:
        # Read N and M, handle leading blank lines
        line = ''
        while line.strip() == '':
            line = sys.stdin.readline()
            if not line:
                return
        parts = line.strip().split()
        # Sometimes split may give only one value if e.g. a blank line was split across reads
        while len(parts) < 2:
            extra = sys.stdin.readline()
            if not extra:
                return
            parts += extra.strip().split()
        N, M = map(int, parts[:2])
        if N == 0 and M == 0:
            break
        intervals = []
        for _ in range(N):
            while True:
                l = sys.stdin.readline()
                if not l:
                    break
                l = l.strip()
                if l != '':
                    break
            d, p = map(int, l.split())
            intervals.append((d, p))
        # Compute baseline expected attacks
        total_expected = 0.0
        # Buckets: p -> sum of all d with this p (for p > 0 only)
        p_buckets = defaultdict(int)
        for d, p in intervals:
            total_expected += d * p
            if p > 0:
                p_buckets[p] += d
        # Allocate the budget greedily, highest p first
        sorted_p = sorted(p_buckets.keys(), reverse=True)
        budget_left = M
        for p in sorted_p:
            if budget_left <= 0:
                break
            use = min(p_buckets[p], budget_left)
            total_expected -= use * p
            budget_left -= use
        # Output as integer if it's integral
        if abs(total_expected - round(total_expected)) < 1e-8:
            print(int(round(total_expected)))
        else:
            # Print with .0 if needed? But always integer per problem.
            print(int(round(total_expected)))

