                    prefix[i][j-1] -
                    prefix[i-1][j-1]
                )

        def rect_sum(r1, c1, r2, c2):
            # inclusive indices
            if r1 > r2 or c1 > c2:
                return 0
            return (
                prefix[r2+1][c2+1] -
                prefix[r1][c2+1] -
                prefix[r2+1][c1] +
                prefix[r1][c1]
            )

        min_ops = float('inf')
        # Rectangle of at least 5 rows and 4 columns
        for top in range(n - 4):
            for bottom in range(top+4, n):
                for left in range(m - 3):
                    for right in range(left+3, m):
                        ops = 0
                        # Left vertical border (excluding corners)
                        if top + 1 <= bottom - 1:
                            rows = bottom - top - 1
                            ones = rect_sum(top+1, left, bottom-1, left)
                            ops += rows - ones  # zeros to become ones
                        # Right vertical border
                        if top + 1 <= bottom - 1:
                            ones = rect_sum(top+1, right, bottom-1, right)
                            ops += (bottom - top - 1) - ones
                        # Top horizontal border (excluding corners)
                        if left + 1 <= right - 1:
                            ones = rect_sum(top, left+1, top, right-1)
                            ops += (right - left - 1) - ones  # zeros to become ones
                        # Bottom horizontal border (excluding corners)
                        if left + 1 <= right - 1:
                            ones = rect_sum(bottom, left+1, bottom, right-1)
                            ops += ones  # ones must become zeros
                        # Inner region: must be all empty
                        innertop = top + 1
                        innerbottom = bottom - 1
                        innerleft = left + 1
                        innerright = right - 1
                        if innertop <= innerbottom and innerleft <= innerright:
                            ones = rect_sum(innertop, innerleft, innerbottom, innerright)
                            ops += ones  # ones to be turned to zeros
                        # Update minimum
                        if ops < min_ops:
                            min_ops = ops
        print(min_ops)

