            # returns sum of grid in inclusive rectangle (r1,c1) to (r2,c2)
            if r1 > r2 or c1 > c2:
                return 0
            return (
                prefix[r2+1][c2+1] - prefix[r1][c2+1] -
                prefix[r2+1][c1] + prefix[r1][c1]
            )

        min_ops = float('inf')

