from math import factorial
MOD = 998244353

def main():
    it = iter(input().split())
    n = int(next(it))
    if n == 1:
        print(1)
        return
    g = [[] for _ in range(n)]
    for _ in range(n-1):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        g[u].append(v)
        g[v].append(u)

    # DP for subtree sizes and parent
    order = []
    st = [0]
    parent = [-1] * n
    while st:
        u = st.pop()
        order.append(u)
        for v in g[u]:
            if v != parent[u]:
                parent[v] = u
                st.append(v)
    sz = [1] * n
    for u in reversed(order):
        p = parent[u]
        if p != -1:
            sz[p] += sz[u]

    # For each node u, number of children that are not leaves
    non_leaf = [0] * n
    for u in range(n):
        for v in g[u]:
            if v != parent[u] and len(g[v]) > 1:
                non_leaf[u] += 1

    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i % MOD

    ans = fact[n]
    for u in range(n):
        ans = ans * fact[non_leaf[u] + 1] % MOD
        for v in g[u]:
            if v != parent[u]:
                ans = ans * pow(sz[v], MOD - 2, MOD) % MOD
    print(ans)

