def cost(a, b, P, M):
    d = abs(b - a)
    return d * (P if b >= a else M)

def main():
    input = sys.stdin.readline
    n_S_M_P = []
    while len(n_S_M_P) < 4:
        n_S_M_P += input().split()
    n, S, M, P = map(int, n_S_M_P)
    x = []
    while len(x) < n:
        x += list(map(int, input().split()))

    MAX_WIN = 450  # number of candidate heights per building

    #DP state: list of (h, val), sorted by h
    # For first building:
    x0 = x[0]
    dp = []
    start = max(1, x0 - MAX_WIN//2)
    end = x0 + MAX_WIN//2
    for h in range(start, end+1):
        c = cost(x0, h, P, M)
        dp.append((h, -c))  # negative cost (no bonus for first)
    # Remove dominated and keep at most MAX_WIN
    if dp:
        dp = sorted(dp, key=lambda t: t[0])
        # Keep only promising states: local maxima and spread out
        new_dp = []
        for i in range(len(dp)):
            h, v = dp[i]
            if i == 0 or i == len(dp)-1:
                new_dp.append((h, v))
            else:
                prev_v = dp[i-1][1]
                nxt_v = dp[i+1][1]
                if v >= prev_v and v >= nxt_v or i % max(1, len(dp)//MAX_WIN) == 0:
                    new_dp.append((h, v))
        # Further prune to MAX_WIN
        if len(new_dp) > MAX_WIN:
            step = max(1, len(new_dp)//MAX_WIN)
            final_dp = []
            for i in range(0, len(new_dp), step):
                final_dp.append(new_dp[i])
            dp = sorted(final_dp, key=lambda t: t[0])
        else:
            dp = sorted(new_dp, key=lambda t: t[0])
    else:
        dp = []

    # For quickly getting best and second best by value
    def best_two(lst):
        if not lst:
            return (-float('inf'), None), (-float('inf'), None)
        vals = [v for _, v in lst]
        idxs = list(range(len(lst)))
        # find top two by value
        sorted_idxs = sorted(idxs, key=lambda i: -vals[i])
        best_i = sorted_idxs[0]
        best_v = vals[best_i]
        best_h = lst[best_i][0]
        if len(sorted_idxs) > 1:
            second_i = sorted_idxs[1]
            second_v = vals[second_i]
            second_h = lst[second_i][0]
        else:
            second_v = -float('inf')
            second_h = None
        return (best_h, best_v), (second_h, second_v)

    for i in range(1, n):
        xi = x[i]
        dp_prev = dp
        # Candidate heights: previous heights, xi near, within a window
        candidates = set()
        if dp_prev:
            # previous heights
            for h, _ in dp_prev:
                candidates.add(h)
                for dh in (-1, 0, 1):
                    candidates.add(xi + dh)
            # window
            min_h = min(h for h, _ in dp_prev) - 200
            max_h = max(h for h, _ in dp_prev) + 200
            for dh in range(min(max_h-xi, 200), max(xi-min_h, -200)+1):
                candidates.add(xi+dh)
        else:
            # Should not happen
            dp = []
            continue

        candidates = {h for h in candidates if h >= 1 and (min_h <= h <= max_h)}
        cand_list = sorted(candidates)

        curr_dp = []
        if not dp_prev:
            continue
        (best_h, best_prev_v), (second_h, second_prev_v) = best_two(dp_prev)

        for h in cand_list:
            # Transition from matching previous height
            match_val = -float('inf')
            c = cost(xi, h, P, M)
            if h in {ph for ph, _ in dp_prev}:
                idx = next((i for i, (ph2, _) in enumerate(dp_prev) if ph2 == h), None)
                if idx is not None:
                    match_val = dp_prev[idx][1] + S - c

            # Transition from any previous height except h (for non-match)
            non_match_val = -float('inf')
            if best_h is not None:
                if best_h != h:
                    # best comes from different height
                    non_match_val = best_prev_v - c
                elif second_h is not None:
                    # best comes from h, but second is different
                    non_match_val = second_prev_v - c
                # else, all previous are h and cannot non-match (then non_match_val stays -inf)
            val = max(match_val, non_match_val)
            if val != -float('inf'):
                curr_dp.append((h, val))

        # Prune curr_dp: remove dominated, keep only spread and maxima, cap at MAX_WIN
        if not curr_dp:
            dp = []
            continue
        curr_dp.sort(key=lambda t: t[0])
        new_dp = []
        for j in range(len(curr_dp)):
            h, v = curr_dp[j]
            if j == 0 or j == len(curr_dp)-1:
                new_dp.append((h, v))
            else:
                prev_v = curr_dp[j-1][1]
                next_v = curr_dp[j+1][1]
                if v >= prev_v and v >= next_v or j % max(1, len(curr_dp)//MAX_WIN) == 0:
                    new_dp.append((h, v))
        # Also cap at MAX_WIN
        if len(new_dp) > MAX_WIN:
            step = max(1, len(new_dp)//MAX_WIN)
            pruned = []
            for j in range(0, len(new_dp), step):
                pruned.append(new_dp[j])
            dp = sorted(pruned, key=lambda t: t[0])
        else:
            dp = sorted(new_dp, key=lambda t: t[0])

    if not dp:
        print(0)
    else:
        print(max(v for _, v in dp))

