import sys
import bisect

def main():
    n, S, M, P = map(int, sys.stdin.readline().split())
    x = list(map(int, sys.stdin.readline().split()))

    # Window size for candidate heights
    R = 120  # Good for n <= 2500 as each state list is small

    def get_candidates(val):
        """Return sorted list of candidate heights around val."""
        low = max(1, val - R)
        high = val + R
        # Use a step for sparser sampling to avoid too many candidates
        step = max(1, (high - low + 20) // 20)
        return list(range(low, high + 1, step)) + [high]

    # DP: states[ ] is a list of (height, dp_value), sorted by height, Pareto pruned
    # First building
    states = []
    for h in get_candidates(x[0]):
        if h >= x[0]:
            cost = (h - x[0]) * P
        else:
            cost = (x[0] - h) * M
        val = -cost
        idx = bisect.bisect_left([s[0] for s in states], h)
        # Remove states to left that are dominated
        while idx > 0 and states[idx-1][1] >= val:
            idx -= 1
        # Remove states to right that are dominated by the new state
        to_remove = []
        for i in range(idx, len(states)):
            if states[i][0] == h:
                if states[i][1] <= val:
                    to_remove.append(i)
                break
            if states[i][1] <= val:
                to_remove.append(i)
            else:
                break
        for i in reversed(to_remove):
            states.pop(i)
        # Remove left again because of previous pops
        while idx > 0 and states[idx-1][1] >= val:
            states.pop(idx-1)
            idx -= 1
        states.insert(idx, (h, val))

    # For the rest of the buildings
    for i in range(1, n):
        xi = x[i]
        nxt = []
        # Candidate heights: previous heights plus small window around current x[i]
        all_cands = set()
        for (ph, _) in states:
            all_cands.add(ph)
            for d in range(-2, 3):
                all_cands.add(max(1, ph+d))
        for h in get_candidates(xi):
            all_cands.add(h)
        all_cands = sorted(all_cands)

        for ch in all_cands:
            # Find best previous state: either with matching height (bonus) or best not greater (no bonus)
            # matching
            idx_match = bisect.bisect_left([s[0] for s in states], ch)
            best_with_bonus = -float('inf')
            if idx_match < len(states) and states[idx_match][0] == ch:
                best_with_bonus = states[idx_match][1] + S

            # not matching: best dp_value for previous height <= ch
            idx_le = bisect.bisect_right([s[0] for s in states], ch) - 1
            best_no_bonus = -float('inf')
            if idx_le >= 0:
                best_no_bonus = max(best_no_bonus, states[idx_le][1])

            best_prev = max(best_with_bonus, best_no_bonus)
            if best_prev == -float('inf'):
                continue # not reachable
            # cost to change current building to ch
            if ch >= xi:
                cost = (ch - xi) * P
            else:
                cost = (xi - ch) * M
            new_val = best_prev - cost

            # Insert into nxt with Pareto pruning
            idx_ins = bisect.bisect_left([s[0] for s in nxt], ch)
            while idx_ins > 0 and nxt[idx_ins-1][1] >= new_val:
                idx_ins -= 1
            to_remove = []
            for j in range(idx_ins, len(nxt)):
                if nxt[j][0] == ch:
                    if nxt[j][1] <= new_val:
                        to_remove.append(j)
                    break
                if nxt[j][1] <= new_val:
                    to_remove.append(j)
                else:
                    break
            for j in reversed(to_remove):
                nxt.pop(j)
            # After pops, maybe shift index
            while idx_ins > 0 and nxt[idx_ins-1][1] >= new_val:
                idx_ins -= 1
            nxt.insert(idx_ins, (ch, new_val))
            # Remove dominated to the right
            j = idx_ins + 1
            while j < len(nxt) and nxt[j][1] <= new_val:
                nxt.pop(j)

        # Post-insert pruning: ensure value increases as height increases
        pruned = []
        best_so_far = -float('inf')
        for h, val in sorted(nxt, key=lambda t: t[0]):
            if val > best_so_far:
                pruned.append((h, val))
                best_so_far = val
        states = pruned

    if not states:
        print(0)
    else:
        print(max(val for (_, val) in states))

