import sys

def cost(orig, new, P, M):
    d = abs(new - orig)
    if new >= orig:
        return d * P
    else:
        return d * M

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    S = int(input_data[idx]); idx += 1
    M = int(input_data[idx]); idx += 1
    P = int(input_data[idx]); idx += 1
    x = list(map(int, input_data[idx:idx + n]))

    OFFSET_LIMIT = 30  # From -30 to +30 relative to original height (adjust if needed for ultra-edge cases)
    # For first building, set DP over allowed offsets
    dp_prev = {}
    base0 = x[0]
    for off in range(-OFFSET_LIMIT, OFFSET_LIMIT + 1):
        h = base0 + off
        c = cost(base0, h, P, M)
        dp_prev[off] = -c  # profit = -cost (no adjacent bonus for first)

    for i in range(1, n):
        dp_curr = {}
        curr_base = x[i]
        delta_x = curr_base - x[i-1]
        for off_cur in range(-OFFSET_LIMIT, OFFSET_LIMIT + 1):
            h_cur = curr_base + off_cur
            cost_cur = cost(curr_base, h_cur, P, M)
            best = -10**30  # -inf

            # Option 1: no adjacent bonus
            if dp_prev:
                best = max(dp_prev.values()) - cost_cur

            # Option 2: match previous building's height for bonus S
            # Need: prev height (x[i-1] + off_prev) == h_cur
            # => off_prev = h_cur - x[i-1] = (curr_base + off_cur) - x[i-1] = (x[i] + off_cur) - x[i-1] = delta_x + off_cur
            off_prev_needed = delta_x + off_cur
            if off_prev_needed in dp_prev:
                cand = dp_prev[off_prev_needed] + S - cost_cur
                if cand > best:
                    best = cand
            # Only store if best is meaningful
            if best > -10**25:
                dp_curr[off_cur] = best

        # Safety check: if dp_curr is empty (shouldn't happen), fallback to previous
        if not dp_curr:
            dp_curr = dict(dp_prev)
        dp_prev = dp_curr

    if not dp_prev:
        print(0)
    else:
        print(max(dp_prev.values()))

