    prev_dp = {}
    for h in (x[0]-1, x[0], x[0]+1):
        if h >= x[0]:
            cost = (h - x[0]) * P
        else:
            cost = (x[0] - h) * M
        prev_dp[h] = -cost   # store negative cost as "profit" (maximize)

    # For the rest of the buildings
    for i in range(1, n):
        candidate_heights = set(prev_dp.keys()) | {x[i]-1, x[i], x[i]+1}
        cur_dp = {}
        for h_cur in candidate_heights:
            # Cost to adjust this building to h_cur
            if h_cur >= x[i]:
                cost = (h_cur - x[i]) * P
            else:
                cost = (x[i] - h_cur) * M

            # Best profit from previous building:
            # Option 1: previous same as current, gain bonus S
            best_match = prev_dp.get(h_cur, -float('inf')) + S
            # Option 2: previous any height, no bonus
            best_any = max(prev_dp.values()) if prev_dp else -float('inf')
            prev_best = max(best_any, best_match)

            if prev_best == -float('inf'):
                continue  # not reachable from any previous state

            net_profit = prev_best - cost
            # Keep the best net profit for this height for current building
            if h_cur in cur_dp:
                if net_profit > cur_dp[h_cur]:
                    cur_dp[h_cur] = net_profit
            else:
                cur_dp[h_cur] = net_profit

