import sys

def main():
    input = sys.stdin.readline

    # Read input: four integers n, S, M, P
    tokens = []
    while len(tokens) < 4:
        tokens += input().split()
    n, S, M, P = map(int, tokens[:4])
    x = []
    while len(x) < n:
        x += list(map(int, input().split()))

    WINDOW = 400  # Candidate window around each x[i]

    # -------- DP for general case, windowed ---------
    dp = {}
    base = x[0]
    for dh in range(-WINDOW, WINDOW + 1):
        h = base + dh
        cost = abs(dh) * (P if dh >= 0 else M)
        dp[h] = -cost  # Negative because we have only cost (no bonus for first building)

    for i in range(1, n):
        xi = x[i]
        new_dp = {}
        prev_heights = list(dp)
        # Candidate current heights: previous heights (to allow match/bonus) and xi ± WINDOW
        candidates = set(prev_heights)
        for dh in range(-WINDOW, WINDOW + 1):
            candidates.add(xi + dh)
        candidates = list(candidates)

        # Precompute max and second max in dp for fast transition
        max1 = -float('inf')
        max1_cnt = 0
        max2 = -float('inf')
        for h_prev, val in dp.items():
            if val > max1:
                max2 = max1
                max1 = val
                max1_cnt = 1
            elif val == max1:
                max1_cnt += 1
            elif val > max2:
                max2 = val

        for h_cur in candidates:
            cost = abs(h_cur - xi) * (P if h_cur > xi else M)

            # Case: previous building has the same height (bonus S)
            if h_cur in dp:
                prev_val = dp[h_cur]
                if max1_cnt > 1 or (max1 == prev_val and max2 == max1):
                    # There is another height with value == max1, so can use max1 for bonus
                    bonus_val = max1 + S - cost
                elif prev_val == max1:
                    # max1 occurs only at h_cur; must fall back to max2 if available
                    bonus_val = max2 + S - cost if max2 != -float('inf') else -float('inf')
                else:
                    bonus_val = prev_val + S - cost
            else:
                bonus_val = -float('inf')

            # Case: previous building has different height (no bonus)
            no_bonus_val = max1 - cost

            best_val = max(bonus_val, no_bonus_val)
            if best_val != -float('inf'):
                new_dp[h_cur] = best_val

        # Prune to keep only heights close to the best (for efficiency)
        if not new_dp:
            # fallback: at least allow xi
            new_dp = {xi: -abs(0)*(P if 0 >= 0 else M)}
        best_h = max(new_dp, key=lambda h: new_dp[h])
        pruned = {}
        for h in new_dp:
            if abs(h - best_h) <= WINDOW:
                if h not in pruned or new_dp[h] > pruned[h]:
                    pruned[h] = new_dp[h]
        dp = pruned

    # ----------- Forced all-equal bonus check -----------
    best_force = -float('inf')
    candidate_heights = set(x)
    min_x = min(x)
    max_x = max(x)
    for h in [min_x - WINDOW, max_x + WINDOW]:
        candidate_heights.add(h)
    for H in candidate_heights:
        total_cost = 0
        for xi in x:
            if H >= xi:
                total_cost += (H - xi) * P
            else:
                total_cost += (xi - H) * M
        bonus = (n - 1) * S
        net = bonus - total_cost
        if net > best_force:
            best_force = net

    # Output the best answer found
    dp_ans = max(dp.values()) if dp else -float('inf')
    print(int(max(dp_ans, best_force)))

