import sys
import math
from itertools import combinations

def robot_pos(x, y, vx, vy, t):
    return (x + vx * t, y + vy * t)

def pairwise_edges(robots, t):
    n = len(robots)
    edges = []
    for i, j in combinations(range(n), 2):
        x1, y1 = robot_pos(robots[i][0], robots[i][1], robots[i][2], robots[i][3], t)
        x2, y2 = robot_pos(robots[j][0], robots[j][1], robots[j][2], robots[j][3], t)
        d = math.hypot(x1 - x2, y1 - y2)
        edges.append((d, i, j))
    return edges

def kruskal_mst_cost(edges, n):
    if n <= 1:
        return 0.0
    edges = sorted(edges)
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    total = 0.0
    used = 0
    for cost, u, v in edges:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
            total += cost
            used += 1
            if used == n-1:
                break
    if used < n-1:
        return float('inf')
    return total

def main():
    input_lines = sys.stdin.read().splitlines()
    idx = 0
    while idx < len(input_lines):
        line = input_lines[idx].strip()
        if not line:
            idx += 1
            continue
        N_T = list(map(int, line.split()))
        if len(N_T) < 2:
            idx += 1
            continue
        N, T = N_T
        if N == 0 and T == 0:
            break
        idx += 1
        robots = []
        for _ in range(N):
            x, y, vx, vy = map(float, input_lines[idx].split())
            robots.append((x, y, vx, vy))
            idx += 1

        # Sample times: 400 points for safety
        STEPS = 400
        if T == 0:
            tvals = [0.0]
        else:
            dt = T / (STEPS - 1) if STEPS > 1 else 0.0
            tvals = [k * dt for k in range(STEPS)]
            tvals.append(0.0)
            tvals.append(T)
            tvals = list(set(tvals))
            tvals = [max(0.0, min(T, t)) for t in tvals]
        min_cost = float('inf')

        for t in tvals:
            edges = pairwise_edges(robots, t)
            cost = kruskal_mst_cost(edges, N)
            if not math.isinf(cost) and cost < min_cost:
                min_cost = cost

        # Try time of minimal pairwise distance for each robot pair (optional refinement)
        for i in range(N):
            for j in range(i+1, N):
                xi, yi, vxi, vyi = robots[i]
                xj, yj, vxj, vyj = robots[j]
                dx0 = xi - xj
                dy0 = yi - yj
                dvx = vxi - vxj
                dvy = vyi - vyj
                denom = dvx*dvx + dvy*dvy
                t_close = None
                if denom > 1e-12:
                    t_star = -(dx0*dvx + dy0*dvy) / denom
                    if 0 - 1e-10 <= t_star <= T + 1e-10:
                        t_star = max(0.0, min(T, t_star))
                        t_close = t_star
                for tc in set(tvals) | ({0.0, T, t_close} if t_close is not None else set()):
                    if 0 <= tc <= T:
                        e = pairwise_edges(robots, tc)
                        c = kruskal_mst_cost(e, N)
                        if not math.isinf(c) and c < min_cost:
                            min_cost = c
        print(f"{min_cost:.8f}")

if __name__ == "__main__":
    main()

import sys
import math

def readints():
    return list(map(int, sys.stdin.readline().split()))

def get_positions(robots, t):
    """Return list of (x, y) positions at time t for all robots."""
    return [(x + vx * t, y + vy * t) for (x, y, vx, vy) in robots]

def distance(p, q):
    dx = p[0] - q[0]
    dy = p[1] - q[1]
    return math.hypot(dx, dy)

def mst_cost(robots, t):
    """Return the total MST cost at time t."""
    n = len(robots)
    positions = get_positions(robots, t)
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            d = distance(positions[i], positions[j])
            edges.append((d, i, j))
    # Kruskal's algorithm
    edges.sort()
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
            return True
        return False
    total_cost = 0.0
    used = 0
    for d, u, v in edges:
        if union(u, v):
            total_cost += d
            used += 1
            if used == n - 1:
                break
    return total_cost

def convex_function_min(f, left, right, iterations=100):
    """
    Ternary (or golden-section) search for minimum of a unimodal (convex) function on [left, right].
    """
    for _ in range(iterations):
        if right - left < 1e-8:
            break
        m1 = left + (right - left) / 3.0
        m2 = right - (right - left) / 3.0
        f1 = f(m1)
        f2 = f(m2)
        if f1 < f2:
            right = m2
        else:
            left = m1
    # Evaluate at endpoints and best found
    best = float('inf')
    best_t = left
    for t in [left, right, (left + right) / 2, m1, m2]:
        val = f(t)
        if val < best:
            best = val
            best_t = t
    # Also check a few extra points for robustness
    step = (right - left) / 20
    t_candidate = left + step
    while t_candidate <= right:
        val = f(t_candidate)
        if val < best:
            best = val
            best_t = t_candidate
        t_candidate += step
    return best

def main():
    while True:
        line = ''
        while line.strip() == '':
            line = sys.stdin.readline()
            if not line:
                return
        parts = line.strip().split()
        if len(parts) < 2:
            continue
        N, T = map(int, parts)
        if N == 0 and T == 0:
            break
        robots = []
        for _ in range(N):
            x, y, vx, vy = map(float, sys.stdin.readline().split())
            robots.append((x, y, vx, vy))
        # Minimize the cost over time in [0, T]
        def cost_at_t(t):
            return mst_cost(robots, t)
        # Check endpoints
        best = min(cost_at_t(0.0), cost_at_t(float(T)))
        # If only one robot, but N >= 2 per constraints, skip that check.
        # We use ternary search if interval is large enough
        if T > 1e-6:
            t_opt = convex_function_min(lambda t: cost_at_t(t), 0.0, float(T))
            best = min(best, cost_at_t(t_opt))
        # Optional: sample more points for better precision
        steps = int(T / 100.0) if T >= 100 else max(10, int(T / 0.1))
        for i in range(steps + 1):
            tt = i * T / steps
            cand = cost_at_t(tt)
            if cand < best:
                best = cand
        # Print the minimum cost found
        print(f"{best:.8f}")

if __name__ == "__main__":
    main()

