import sys
import math

def dog_intercept_time(dog, frisbee, t_launch):
    """
    Returns the earliest tau >= 0 such that dog can reach the frisbee at time tau (after launch),
    moving at most at dog['speed'] in a straight line, accounting for moving frisbee.
    If impossible, returns None.
    """
    fx0, fy0 = frisbee['pos0']
    fvx, fvy = frisbee['vel']
    dog_x, dog_y = dog['pos']
    V = dog['speed']

    # The frisbee at time tau after launch is at:
    #   (fx0 + fvx*tau, fy0 + fvy*tau)
    # The dog can move at most V * tau in any direction from (dog_x, dog_y)
    # So we need the minimal tau >= 0 solving:
    #   sqrt((fx0 + fvx*tau - dog_x)^2 + (fy0 + fvy*tau - dog_y)^2) <= V * tau + 1e-8
    def dist_sq(tau):
        fx = fx0 + fvx * tau
        fy = fy0 + fvy * tau
        dx = fx - dog_x
        dy = fy - dog_y
        return dx*dx + dy*dy

    # At tau=0
    d0 = math.hypot(fx0 - dog_x, fy0 - dog_y)
    if d0 <= 1e-8:
        return 0.0

    # Quadratic form:
    # (fvx^2 + fvy^2 - V^2) * tau^2 + 2*(fvx*(fx0-dog_x) + fvy*(fy0-dog_y)) * tau + ((fx0-dog_x)^2 + (fy0-dog_y)^2) - V^2*tau^2  <= 0
    A = fvx*fvx + fvy*fvy - V*V
    B = 2*(fvx*(fx0-dog_x) + fvy*(fy0-dog_y))
    C = (fx0-dog_x)**2 + (fy0-dog_y)**2

    # Edge case: stationary frisbee
    if abs(A) < 1e-12:
        # Linear or constant
        if abs(B) < 1e-12:
            # Only possible if C <= 0
            if C <= 1e-8:
                return 0.0
            else:
                return None
        else:
            # B*tau + C <= 0
            if B > 0:
                # solution for tau >= -C/B
                tau0 = -C / B
                if tau0 > -1e-8:
                    return max(tau0, 0.0)
                else:
                    return None
            else:
                # B < 0
                tau0 = -C / B
                if tau0 > -1e-8 and tau0 > 0.0 - 1e-8:
                    return max(0.0, tau0)
                else:
                    # Maybe at tau=0?
                    if d0 <= V*1e-8:
                        return 0.0
                    else:
                        return None

    # Quadratic inequality: A*tau^2 + B*tau + C <= V^2*tau^2 actually handled by our A redefinition,
    # So we want to solve (A*tau^2 + B*tau + C) <= 0
    # But actually from the distance-velocity constraint:
    # dist_sq(tau) <= (V*tau)**2  => (fvx^2+fvy^2 - V^2) * tau^2 + 2*(fvx*(fx0-dog_x)+fvy*(fy0-dog_y))*tau + ((fx0-dog_x)^2+(fy0-dog_y)^2) <= 0
    # which is the above A,B,C
    roots = []
    disc = B*B - 4*A*C
    if disc < -1e-12:
        # No solution
        return None
    sqrt_disc = math.sqrt(max(0.0, disc))
    r1 = (-B - sqrt_disc) / (2*A)
    r2 = (-B + sqrt_disc) / (2*A)
    if A > 0:
        # Valid if between roots
        lo = max(r1, r2)
        hi = min(r1, r2)
        if lo < hi:
            lo, hi = min(r1, r2), max(r1, r2)
        # Actually, valid for tau in [smaller, larger] IF they are real and A>0
        if hi < lo:
            lo, hi = r2, r1
        lower = max(lo, 0.0)
        if lower <= hi - 1e-12:
            # Check at lower
            dist_val = math.sqrt(dist_sq(lower))
            if dist_val <= V*lower + 1e-8:
                return lower
            # Otherwise, binary search in [lower, hi]
            left, right = lower, hi
            for _ in range(100):
                mid = (left+right)/2
                if math.sqrt(dist_sq(mid)) <= V*mid + 1e-8:
                    right = mid
                else:
                    left = mid
            return right
        else:
            # Only possible if at tau=0 or in a gap including 0
            if 0.0 >= lo - 1e-12 and 0.0 <= hi + 1e-12:
                # should have been caught already
                if math.sqrt(dist_sq(0.0)) <= V*0.0 + 1e-8:
                    return 0.0
                else:
                    # Try nearby
                    for t in [1e-5, 1e-4, 0.001]:
                        if math.sqrt(dist_sq(t)) <= V*t + 1e-8:
                            return t
                    return None
            elif A > 0 and hi < 0:
                # No solution for tau >=0
                return None
            elif A > 0 and lo > 0:
                # Only possible at lo
                if math.sqrt(dist_sq(lo)) <= V*lo + 1e-8:
                    return lo
                else:
                    return None
            else:
                # Edge, try binary search in [0, upper_bound]
                pass
    else:  # A < 0
        # Valid outside roots: tau <= min(r1, r2) or tau >= max(r1, r2)
        roots_sorted = sorted([r1, r2])
        # Try tau in [0, roots_sorted[0]] if roots_sorted[0] >= 0, or [roots_sorted[1], ...] if roots_sorted[1] >=0
        found = None
        # Option 1: tau in [0, roots_sorted[0]]
        if roots_sorted[0] >= -1e-8:
            lo = 0.0
            hi = max(roots_sorted[0], 0.0)
            if hi > lo + 1e-12:
                for _ in range(100):
                    mid = (lo+hi)/2
                    if math.sqrt(dist_sq(mid)) <= V*mid + 1e-8:
                        hi = mid
                    else:
                        lo = mid
                candidate = hi
                if candidate > lo and math.sqrt(dist_sq(candidate)) <= V*candidate + 1e-8:
                    found = candidate
            else:
                if math.sqrt(dist_sq(0.0)) <= V*0.0 + 1e-8:
                    found = 0.0
        # Option 2: tau >= roots_sorted[1]
        if found is None and roots_sorted[1] > -1e-8:
            lo = max(roots_sorted[1], 0.0)
            hi = 1e5
            for _ in range(100):
                mid = (lo+hi)/2
                if math.sqrt(dist_sq(mid)) <= V*mid + 1e-8:
                    hi = mid
                else:
                    lo = mid
            candidate = hi
            if math.sqrt(dist_sq(candidate)) <= V*candidate + 1e-8:
                found = candidate
        if found is None:
            # Try a quick binary search in a big interval
            lo = 0.0
            hi = 1e5
            for _ in range(100):
                mid = (lo+hi)/2
                if math.sqrt(dist_sq(mid)) <= V*mid + 1e-8:
                    hi = mid
                else:
                    lo = mid
            candidate = hi
            if math.sqrt(dist_sq(candidate)) <= V*candidate + 1e-8:
                found = candidate
        return found if found is not None and found >= 0.0 - 1e-12 else None

    # Fallback: binary search over a reasonable range
    # We try last-resort binary search up to 10000 seconds
    lo, hi = 0.0, 10000.0
    best = None
    for _ in range(100):
        mid = (lo+hi)/2
        if math.sqrt(dist_sq(mid)) <= V*mid + 1e-8:
            best = mid
            hi = mid
        else:
            lo = mid
    if best is not None and best >= 0.0 - 1e-12:
        # Final check
        if math.sqrt(dist_sq(best)) <= V*best + 1e-8:
            return best
    # Also check for tau=0
    if math.sqrt(dist_sq(0.0)) <= V*0.0 + 1e-8:
        return 0.0
    return None

def main():
    import sys
    EPS = 1e-12
    while True:
        # Read first non-empty line: N and M
        while True:
            line = sys.stdin.readline()
            if not line:
                return
            if line.strip() != '':
                break
        parts = line.strip().split()
        if len(parts)<2:
            parts += sys.stdin.readline().strip().split()
        N, M = map(int, parts)
        if N == 0 and M == 0:
            break
        dogs = []
        for _ in range(N):
            while True:
                ln = sys.stdin.readline()
                if ln is None or ln.strip() != '':
                    break
            x, y, v = map(float, ln.strip().split())
            dogs.append({
                'pos': [x, y],
                'vel': [0.0, 0.0],  # not used, but kept for completeness
                'speed': v,
                'count': 0
            })
        frisbees = []
        for _ in range(M):
            while True:
                ln = sys.stdin.readline()
                if ln is None or ln.strip() != '':
                    break
            fx, fy, fvx, fvy = map(float, ln.strip().split())
            frisbees.append({'pos0': [fx, fy], 'vel': [fvx, fvy]})

        current_time = 0.0
        for fris in frisbees:
            # For each dog, compute intercept time (time after launch: tau)
            intercepts = []
            fx0, fy0 = fris['pos0']
            fvx, fvy = fris['vel']
            for dog in dogs:
                t = dog_intercept_time(dog, fris, 0.0)
                intercepts.append(t if t is not None and t >= -EPS else float('inf'))

            # Find minimal tau
            min_t = min(intercepts)
            if min_t > current_time + 1e9:  # shouldn't happen, but defensive
                min_t = 1e-9

            winner = -1
            for i in range(N):
                if abs(intercepts[i] - min_t) < 1e-8 and intercepts[i] == min_t and intercepts[i] >= 0:
                    winner = i
                    break

            # All dogs but the winner stay put
            # Only winner moves toward interception point
            dt = min_t  # time to move after current frisbee is launched
            if dt < 0:
                dt = 0.0
            if winner != -1:
                dog = dogs[winner]
                fx_end = fx0 + fvx * dt
                fy_end = fy0 + fvy * dt
                dx = fx_end - dog['pos'][0]
                dy = fy_end - dog['pos'][1]
                dist = math.hypot(dx, dy)
                if dist < 1e-8:
                    dog['pos'] = [fx_end, fy_end]
                else:
                    # Max displacement this interval at dog's speed
                    move_len = min(dist, dog['speed'] * dt)
                    dxn = dx * move_len / dist if dist > 1e-8 else 0.0
                    dyn = dy * move_len / dist if dist > 1e-8 else 0.0
                    newx = dog['pos'][0] + dxn
                    newy = dog['pos'][1] + dyn
                    # Clamp to endpoint if almost there (to avoid floating errors)
                    if math.hypot(newx - fx_end, newy - fy_end) < 1e-8:
                        dog['pos'] = [fx_end, fy_end]
                    else:
                        dog['pos'] = [newx, newy]
            # Others remain unchanged
            # Advance simulation time
            current_time += dt
            dogs[winner]['count'] += 1

        # Output result
        print(' '.join(str(d['count']) for d in dogs))

if __name__ == "__main__":
    main()

import sys
from collections import deque

def main():
    n_m = sys.stdin.readline().split()
    if not n_m:
        return
    n, m = map(int, n_m)

    employee_groups = []
    for _ in range(n):
        parts = sys.stdin.readline().split()
        if not parts:
            # In case of empty line, read again
            parts = sys.stdin.readline().split()
        k = int(parts[0])
        langs = set()
        if k > 0:
            langs = set(map(int, parts[1:]))
        employee_groups.append(langs)

    # Union-Find (Disjoint Set Union) for employees
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    # Union employees who know at least one common language
    # For every language, gather all employees who know it, then union them
    lang_to_emps = {}
    for emp_idx, langs in enumerate(employee_groups):
        for lang in langs:
            if lang not in lang_to_emps:
                lang_to_emps[lang] = []
            lang_to_emps[lang].append(emp_idx)
    for emps in lang_to_emps.values():
        if len(emps) > 1:
            first = emps[0]
            for e in emps[1:]:
                union(first, e)

    # Find connected components (value of n with no languages: all separate)
    from collections import defaultdict
    comp_id = [None] * n
    comp_map = defaultdict(list)
    for idx in range(n):
        root = find(idx)
        if comp_id[idx] is None:
            comp_id[idx] = root
        comp_map[root].append(idx)

    # For each component:
