    # Employee DSU
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra != rb:
            parent[ra] = rb

    # Group employees by language, then union all in the same group
    lang_to_emps = defaultdict(list)
    for emp_idx, langs in enumerate(employees_languages):
        for lang in langs:
            lang_to_emps[lang].append(emp_idx)

    for emp_list in lang_to_emps.values():
        if len(emp_list) > 1:
            first = emp_list[0]
            for emp in emp_list[1:]:
                union(first, emp)

    roots = set()
    for i in range(n):
        roots.add(find(i))
    num_components = len(roots)
    print(max(0, num_components - 1))

