import sys
from collections import defaultdict

MOD = 10**9 + 7

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    nums = data[2:2+n]

    def is_lucky(x):
        s = str(x)
        return all(c in {'4','7'} for c in s)

    # Separate lucky and non-lucky numbers
    lucky_values = []
    non_lucky_count = 0
    from collections import defaultdict as dd
    freq_lucky = dd(int)
    idx = 0
    for x in nums:
        if is_lucky(x):
            lucky_values.append(x)
            freq_lucky[x] += 1
        else:
            non_lucky_count += 1

    m = len(lucky_values)

    # DP: dp[j] = number of ways to pick j DISTINCT lucky values, each from any of their occurrences
    dp = [0] * (k+1)
    dp[0] = 1
    # For each unique lucky value, update dp (can only pick it once)
    for cnt in freq_lucky.values():
        # need to update from the end to avoid using the same value more than once per step
        ndp = dp[:]
        for j in range(min(k, m), -1, -1):
            if dp[j]:
                # pick this value once (from cnt choices of occurrence), move to j+1
                add = (dp[j] * cnt) % MOD
                if j+1 <= k:
                    ndp[j+1] = (ndp[j+1] + add) % MOD
        dp = ndp

    # Precompute nCr for non_lucky_count and k (k <= n <= 1e5)
    max_n = non_lucky_count
    max_r = k

    # If non_lucky_count < 0, but it can't be
    if max_n < 0:
        fact = [1]
        inv_fact = [1]
    else:
        fact = [1] * (max_n+1)
        for i in range(1, max_n+1):
            fact[i] = fact[i-1] * i % MOD

        inv_fact = [1] * (max_n+1)
        if max_n >= 1:
            inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
            for i in range(max_n-1, -1, -1):
                inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

        def comb(nr, rr):
            if rr < 0 or rr > nr:
                return 0
            return fact[nr] * inv_fact[rr] % MOD * inv_fact[nr-rr] % MOD

    # For each i from 0 to min(k, m), total ways: pick i different lucky values (dp[i] ways), pick (k-i) different non-lucky indices (comb(non_lucky_count, k-i))
    ans = 0
    max_i = min(k, m)
    for i in range(0, max_i+1):
        need_non = k - i
        if 0 <= need_non <= non_lucky_count:
            ans = (ans + dp[i] * comb(non_lucky_count, need_non)) % MOD
    print(ans % MOD)

if __name__ == '__main__':
    main()

