import sys

def main():
    N = int(sys.stdin.readline())
    blocks = []
    for _ in range(N):
        w, h = map(int, sys.stdin.readline().split())
        a, b = sorted((w, h))
        blocks.append((a, b))
    # Sort blocks: by width (a) descending, then by height (b) descending
    blocks.sort(key=lambda x: (-x[0], -x[1]))

    # Build DAG edges: i -> j if block j can immediately go on block i
    adj = [[] for _ in range(N)]
    for i in range(N):
        for j in range(i+1, N):
            if blocks[j][0] < blocks[i][0] and blocks[j][1] < blocks[i][1]:
                adj[i].append(j)

    # Build bipartite graph for maximum matching: left[i] -> right[j] if i -> j is an edge in DAG
    graph = [[] for _ in range(N)]
    for i in range(N):
        for j in adj[i]:
            graph[i].append(j)

    # Hopcroft-Karp or DFS (Kuhn) for maximum bipartite matching
    def dfs(u, seen, match_to_right):
        for v in graph[u]:
            if not seen[v]:
                seen[v] = True
                # If v is not matched or previous match can be rematched
                if match_to_right[v] == -1 or dfs(match_to_right[v], seen, match_to_right):
                    match_to_right[v] = u
                    return True
        return False

    match_to_right = [-1] * N  # right node v matched to left node
    matching_size = 0
    for u in range(N):
        seen = [False] * N
        if dfs(u, seen, match_to_right):
            matching_size += 1

    # Minimal number of piles = N - size of maximum matching
    print(N - matching_size)

