import sys
import math

def main():
    # Read all tokens and lines
    lines = []
    while True:
        try:
            line = input()
            if line.strip() == '':
                continue
            lines.append(line.rstrip('\n'))
        except EOFError:
            break
    if not lines:
        return
    n_c1_c2 = lines[0].split()
    if len(n_c1_c2) < 3:
        # If input split across lines
        n_c1_c2 += lines[1].split()
        lines = lines[1:][1:]  # skip already used part
    n, c1, c2 = map(int, n_c1_c2)
    s = ""
    for l in lines[1:]:
        s += l
    if len(s) < n:
        # In case input was split even more
        s = s[:n]
    adults = s.count('1')
    pupils = n - adults

    if pupils == 0:
        # Only adults, each in their own group
        print(adults * c1)
        return

    # Candidate k values: number of groups must be between adults and n inclusive
    candidates = {adults, n}
    # Approximate optimal group size unconstrained:
    x_opt = 1.0
    if c2 > 0:
        try:
            x_opt = 1 + math.sqrt(c1 / c2)
        except:
            x_opt = 1.0
    x_opt = max(1.0, x_opt)
    k_opt = max(1, min(n, int(round(n / x_opt))))
    for dk in (-2, -1, 0, 1, 2):
        k = max(adults, min(n, k_opt + dk))
        candidates.add(k)
    # Try a few more spread out values just in case
    if adults + 10 <= n:
        candidates.add(adults + 10)
    if adults * 2 <= n:
        candidates.add(adults * 2)
    # Remove candidates outside range
    candidates = {k for k in candidates if adults <= k <= n}

    def group_cost(k):
        """
        Compute total cost for splitting n people into k groups
        as evenly as possible, with each group at least 1 adult (k <= adults ensures this).
        """
        # n people into k groups: m = floor(n/k), r = n%k
        m = n // k
        r = n % k
        # r groups have size m+1, k-r groups have size m
        # Cost per group of size s: c1 + c2*(s-1)**2
        cost_r = c1 + c2 * (m) ** 2 if m >= 1 else c1  # since m==0 only if n<k but that's not possible
        # For group size (m+1): (size-1)=m
        # For group size m: (size-1)=m-1 (if m>1), else 0 (if m==1)
        if m > 1:
            cost_m = c1 + c2 * (m - 1) ** 2
        elif m == 1:
            cost_m = c1  # (1-1)=0
        else:  # m==0 (shouldn't happen as n>=k)
            cost_m = c1
        total_cost = r * cost_r + (k - r) * cost_m
        return total_cost

    min_total = float('inf')
    for k in candidates:
        cost = group_cost(k)
        if cost < min_total:
            min_total = cost

    print(min_total)

